css_scrollbar:
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: #0a0a0c; }
::-webkit-scrollbar-thumb { background: var(--sl-primary); border-radius: 10px; }
::-webkit-scrollbar-thumb:hover { background: var(--sd-cyan, #0dcaf0); }

css_card_zoom_cinematografico:
.card-game {
  overflow: hidden;
  transition: transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;
}
.card-game:hover {
  transform: translateY(-5px);
  box-shadow: 0 10px 25px rgba(13, 202, 240, 0.15);
  border-color: var(--sl-primary) !important;
}
.card-game img {
  transition: transform 0.5s ease;
}
.card-game:hover img {
  transform: scale(1.05);
}

css_fallback_holografico:
.card-game div.img-container {
  background-color: #0a0a0c !important;
  background-image:
    linear-gradient(rgba(13, 202, 240, 0.08) 1px, transparent 1px),
    linear-gradient(90deg, rgba(13, 202, 240, 0.08) 1px, transparent 1px);
  background-size: 25px 25px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.card-game div.img-container::before {
  content: 'NO SIGNAL //';
  font-family: 'Rajdhani', monospace;
  color: rgba(13, 202, 240, 0.6);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 5px;
  text-shadow: 0 0 10px rgba(13, 202, 240, 0.4);
  animation: signal-flicker 3s infinite;
}
@keyframes signal-flicker {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; text-shadow: 0 0 2px rgba(13, 202, 240, 0.2); }
  52% { opacity: 0.3; }
  54% { opacity: 0.8; }
}
